def compute(payload):
    """按事务、语句、行变更生成已解码的列映射。D 用空对象；类型错误用 null，使整合端按事务回滚。"""
    txs = payload["txs"]
    result = []
    for tx in txs:
        tx_rows = []
        for statement in tx["statements"]:
            stmt_rows = []
            for change in statement:
                op = change["op"]
                if op == "D":
                    stmt_rows.append({})
                    continue
                cols = change.get("cols", [])
                decoded = {}
                ok = True
                for col in cols:
                    name = col["name"]
                    ctype = col["type"]
