sys.path.insert(0, str(ROOT))

from components.column_decoding.work import compute


class TestColumnDecoding(unittest.TestCase):
    def test_public_example(self):
        payload = {
            "txs": [
                {
                    "lsn": 1,
                    "statements": [
                        [
                            {"op": "U", "old": "a", "cols": [{"name": "key", "type": "text", "value": "b"}]},
                            {"op": "U", "old": "b", "cols": [
                                {"name": "key", "type": "text", "value": "a"},
                                {"name": "body", "type": "text", "value": None},
                            ]},
                        ]
                    ],
                }
            ]
        }
        self.assertEqual(compute(payload), [[[{"key": "b"}, {"key": "a", "body": None}]]])

    def test_delete_empty_object(self):
        payload = {"txs": [{"lsn": 2, "statements": [[{"op": "D", "old": "x"}]]}]}
        self.assertEqual(compute(payload), [[[{}]]])

    def test_int_decoding_and_type_error(self):
        payload = {
            "txs": [
                {
                    "lsn": 3,
                    "statements": [
                        [
                            {"op": "I", "cols": [
                                {"name": "key", "type": "text", "value": "k"},
                                {"name": "body", "type": "text", "value": "hello"},
                                {"name": "rank", "type": "int", "value": "42"},
                            ]},
                            {"op": "U", "old": "k", "cols": [
                                {"name": "rank", "type": "int", "value": "not-an-int"},
                            ]},
                        ]
                    ],
                }
            ]
        }
        self.assertEqual(
            compute(payload),
            [[[{"key": "k", "body": "hello", "rank": 42}, None]]],
        )

    def test_null_rank_preserved(self):
        payload = {"txs": [{"lsn": 4, "statements": [[
            {"op": "I", "cols": [
                {"name": "key", "type": "text", "value": "k"},
                {"name": "body", "type": "text", "value": None},
                {"name": "rank", "type": "int", "value": None},
            ]},
        ]]}]}
        self.assertEqual(compute(payload), [[[{"key": "k", "body": None, "rank": None}]]])


if __name__ == "__main__":
    unittest.main()

