                if nk in snapshot:
                    aborted = True
                    break
                snapshot[nk] = nv
            if aborted:
                break

        if aborted:
            log.append([lsn, "ABORT"])
        else:
            rows = snapshot
            committed.add(lsn)
            log.append([lsn, "COMMIT"])

    return {"log": log, "rows": rows}

